    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); cells = []
            while q:
                y, x = q.popleft(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == col:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((col, cells))
    # The long L-shaped component is the color key. Recolor the nearest
    # straight vertical component of another color with that key color.
    markers = []
    for col, cells in comps:
        rs = {r for r,c in cells}; cs = {c for r,c in cells}
        if len(cells) >= 7 and col != bg and len(rs) >= 4 and len(cs) >= 4:
            markers.append((len(cells), col, cells))
    if not markers:
        return out
    _, key, marker = max(markers)
    candidates = []
    for col, cells in comps:
        if col in (bg, key) or len(cells) < 2:
