            dist = min(abs(r-y)+abs(c-x) for r,c in cells for y,x in marker)
            candidates.append((dist, -len(cells), cells))
    if candidates:
        _, _, cells = min(candidates)
        for r,c in cells:
            out[r][c] = key
    return out

