def _components(grid):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid)

    # The longest joined L-shaped line is a direction/color marker. Its
    # vertical arm points away from the object to recolor.
    markers = []
    for color, cells in comps:
        if color == bg or len(cells) < 4:
            continue
        row_counts = Counter(r for r, c in cells)
        col_counts = Counter(c for r, c in cells)
        for r, nrow in row_counts.items():
            for c, ncol in col_counts.items():
                if nrow >= 2 and ncol >= 2 and (r, c) in cells:
                    markers.append((len(cells), color, cells, r, c, row_counts, col_counts))
    if not markers:
        return out
    _, key_color, marker, elbow_r, elbow_c, row_counts, col_counts = max(markers, key=lambda x: (x[0], max(x[5].values()) + max(x[6].values())))

    # Determine whether the vertical marker arm extends up or down from elbow.
    min_r = min(r for r, c in marker)
    max_r = max(r for r, c in marker)
    vertical_down = max_r > elbow_r
    vertical_up = min_r < elbow_r
    if vertical_down and not vertical_up:
        wanted_side = -1
    elif vertical_up and not vertical_down:
        wanted_side = 1
    else:
        return out

    candidates = []
    marker_set = set(marker)
    for color, cells in comps:
        if set(cells) == marker_set or color == bg:
            continue
        center_r = sum(r for r, c in cells) / len(cells)
        if (center_r - elbow_r) * wanted_side <= 0:
            continue
        distance = min(abs(r - elbow_r) + abs(c - elbow_c) for r, c in cells)
        candidates.append((distance, -len(cells), cells))
    if candidates:
        target = min(candidates, key=lambda x: (x[0], x[1]))[2]
        for r, c in target:
            out[r][c] = key_color
    return out

